import java.io.*; import java.util.*; public class TestClass { static class Edge { int to; long weight; Edge(int to, long weight) { this.to = to; this.weight = weight; } } static class Node implements Comparable<Node> { int id; long dist; Node(int id, long dist) { this.id = id; this.dist = dist; } public int compareTo(Node other) { return Long.compare(this.dist, other.dist); } } static List<List<Edge>> adj; static int leafOffset; static void build(int node, int start, int end) { if (start == end) { leafOffset = Math.max(leafOffset, node); return; } int mid = (start + end) / 2; adj.get(node).add(new Edge(2 * node, 0)); adj.get(node).add(new Edge(2 * node + 1, 0)); build(2 * node, start, mid); build(2 * node + 1, mid + 1, end); } static void addEdge(int node, int start, int end, int l, int r, int target, long weight) { if (start > end || start > r || end < l) return; if (start >= l && end <= r) { adj.get(node).add(new Edge(target, weight)); return; } int mid = (start + end) / 2; addEdge(2 * node, start, mid, l, r, target, weight); addEdge(2 * node + 1, mid + 1, end, l, r, target, weight); } public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String lineT = br.readLine(); if (lineT == null) return; int T = Integer.parseInt(lineT.trim()); while (T-- > 0) { String[] line = br.readLine().trim().split("\\s+"); int N = Integer.parseInt(line[0]); int M = Integer.parseInt(line[1]); int treeSize = 4 * N; adj = new ArrayList<List<Edge>>(treeSize + N + 1); for (int i = 0; i <= treeSize + N; i++) adj.add(new ArrayList<Edge>()); build(1, 1, N); for (int i = 1; i <= N; i++) { int nodeIdx = 1; int s = 1, e = N; while (s != e) { int mid = (s + e) / 2; if (i <= mid) { nodeIdx = 2 * nodeIdx; e = mid; } else { nodeIdx = 2 * nodeIdx + 1; s = mid + 1; } } adj.get(nodeIdx).add(new Edge(treeSize + i, 0)); } for (int i = 0; i < M; i++) { String[] arr = br.readLine().trim().split("\\s+"); int L = Integer.parseInt(arr[0]); int R = Integer.parseInt(arr[1]); long W = Long.parseLong(arr[2]); addEdge(1, 1, N, L, R, treeSize + R, W); } long[] dist = new long[treeSize + N + 1]; Arrays.fill(dist, Long.MAX_VALUE); PriorityQueue<Node> pq = new PriorityQueue<Node>(); dist[treeSize + 1] = 0; pq.add(new Node(treeSize + 1, 0)); while (!pq.isEmpty()) { Node curr = pq.poll(); if (curr.dist > dist[curr.id]) continue; for (Edge edge : adj.get(curr.id)) { if (dist[edge.to] > dist[curr.id] + edge.weight) { dist[edge.to] = dist[curr.id] + edge.weight; pq.add(new Node(edge.to, dist[edge.to])); } } } long ans = dist[treeSize + N]; System.out.println(ans == Long.MAX_VALUE ? -1 : ans); } } }